package dev.psxlab;
import android.content.SharedPreferences;
import android.view.KeyEvent;
import dev.psxlab.core.PadState;
import java.lang.reflect.Proxy;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class ControllerProfileTest {
    private SharedPreferences prefs(Map<String,Object> map){return (SharedPreferences)Proxy.newProxyInstance(SharedPreferences.class.getClassLoader(),new Class[]{SharedPreferences.class},(p,m,a)->{switch(m.getName()){case "contains":return map.containsKey(a[0]);case "getString":case "getInt":case "getBoolean":return map.getOrDefault(a[0].toString(),a[1]);case "getAll":return map;default:throw new UnsupportedOperationException(m.getName());}});}
    @Test public void manualBindingOverridesAutomaticInputAndReleasesOtherHeldKeys(){Map<String,Object> values=new HashMap<>();values.put(ControllerProfile.pref("pad",13),"k:"+KeyEvent.KEYCODE_BUTTON_A);ControllerProfile profile=new ControllerProfile(prefs(values),"pad",0);PadState pad=new PadState();GamepadInput input=new GamepadInput(pad);input.configure(profile);assertTrue(input.key(KeyEvent.KEYCODE_BUTTON_A,true));assertEquals(1<<13,pad.get().pressed());input.key(KeyEvent.KEYCODE_BUTTON_L1,true);input.key(KeyEvent.KEYCODE_BUTTON_A,false);assertEquals(1<<10,pad.get().pressed());}
    @Test public void sensitivityDeadZoneAndInversionAreIndependent(){Map<String,Object> values=new HashMap<>();values.put("deadzone_0",10);values.put("sensitivity_0",200);values.put("invert_0_1",true);PadState pad=new PadState();GamepadInput input=new GamepadInput(pad);input.configure(new ControllerProfile(prefs(values),"pad",0));input.axes(.2f,.2f,0,0,0,0,0,0);assertEquals(179,pad.get().leftX());assertEquals(77,pad.get().leftY());input.axes(.08f,0,0,0,0,0,0,0);assertEquals(128,pad.get().leftX());}
    @Test public void defaultProfilePreservesStickValuesOutsideDeadZone(){PadState pad=new PadState();GamepadInput input=new GamepadInput(pad);input.configure(new ControllerProfile(prefs(new HashMap<>()),"pad",0));input.axes(1,0,.25f,-.75f,0,0,0,0);assertEquals(159,pad.get().rightX());assertEquals(32,pad.get().rightY());}
    @Test public void keyboardButtonsCanDriveBothDirectionsOfAnalogAxes(){Map<String,Object> values=new HashMap<>();values.put(ControllerProfile.pref("keyboard",212),"k:"+KeyEvent.KEYCODE_W);values.put(ControllerProfile.pref("keyboard",213),"k:"+KeyEvent.KEYCODE_S);PadState pad=new PadState();GamepadInput input=new GamepadInput(pad);input.configure(new ControllerProfile(prefs(values),"keyboard",0));input.key(KeyEvent.KEYCODE_W,true);assertEquals(0,pad.get().leftY());input.key(KeyEvent.KEYCODE_S,true);assertEquals(128,pad.get().leftY());input.key(KeyEvent.KEYCODE_W,false);assertEquals(255,pad.get().leftY());input.key(KeyEvent.KEYCODE_S,false);assertEquals(128,pad.get().leftY());}
    @Test public void deviceProfilesAndAutomaticResetDoNotReplaceOtherDevices(){Map<String,Object> values=new HashMap<>();values.put(ControllerProfile.pref("one",14),"k:"+KeyEvent.KEYCODE_BUTTON_X);ControllerProfile one=new ControllerProfile(prefs(values),"one",0),two=new ControllerProfile(prefs(values),"two",0);assertEquals(Integer.valueOf(1<<14),one.keyMasks.get(KeyEvent.KEYCODE_BUTTON_X));assertEquals(Integer.valueOf(1<<14),two.keyMasks.get(KeyEvent.KEYCODE_BUTTON_A));values.put("automatic_one",true);one=new ControllerProfile(prefs(values),"one",0);assertEquals(Integer.valueOf(1<<14),one.keyMasks.get(KeyEvent.KEYCODE_BUTTON_A));}
    @Test public void hotkeyAxesReserveTheirDefaultGameInputAndAxesCanBeUnbound(){Map<String,Object> values=new HashMap<>();values.put(ControllerProfile.pref("pad",100),"a:17:1");values.put(ControllerProfile.pref("pad",200),"none");values.put(ControllerProfile.pref("pad",101),"k:"+KeyEvent.KEYCODE_BUTTON_X);ControllerProfile p=new ControllerProfile(prefs(values),"pad",0);assertTrue(p.reservedAxis(17));assertEquals(0,p.automaticAxisMask()&256);assertEquals(-2,p.axes[0]);assertEquals(2,p.keyHotkeys(KeyEvent.KEYCODE_BUTTON_X));}
}
